#include <cstddef>

struct PlainPoint
{
    double x{};
    double y{};
};

struct VirtualPoint
{
    double x{};
    double y{};
    virtual ~VirtualPoint() = default;
};

std::size_t vptrCost()
{
    return sizeof(VirtualPoint) - sizeof(PlainPoint);
}

unitTests:
static_assert(!std::is_polymorphic_v<PlainPoint>, "PlainPoint should have no virtual functions");
static_assert(std::is_polymorphic_v<VirtualPoint>, "VirtualPoint needs a virtual destructor");
TEST("the difference is exactly one pointer") { CHECK_EQ(sizeof(PlainPoint), 2 * sizeof(double)); CHECK_EQ(vptrCost(), sizeof(void*)); }

